<template><div class="app-container"><el-form :inline="true" :model="query"><el-form-item label="状态"><el-select v-model="query.status" clearable style="width:150px"><el-option v-for="s in ['QUEUED','PROCESSING','SUCCEEDED','FAILED','CANCELLED']" :key="s" :label="s" :value="s" /></el-select></el-form-item><el-form-item label="提示词"><el-input v-model="query.keyword" clearable /></el-form-item><el-button type="primary" @click="load">查询</el-button></el-form><el-table v-loading="loading" :data="rows"><el-table-column prop="taskId" label="任务ID" width="90"/><el-table-column prop="userId" label="用户ID" width="90"/><el-table-column prop="taskType" label="类型" width="130"/><el-table-column prop="prompt" label="提示词" show-overflow-tooltip/><el-table-column prop="creditCost" label="算力" width="90"/><el-table-column prop="status" label="状态" width="120"/><el-table-column prop="progress" label="进度" width="90"><template #default="s">{{ s.row.progress }}%</template></el-table-column><el-table-column prop="createTime" label="创建时间" width="180"/></el-table></div></template>
<script setup name="VizoraTask">
import { listTasks } from '@/api/vizora/operation'
const rows = ref([]); const loading = ref(false); const query = reactive({ status: undefined, keyword: undefined })
async function load() { loading.value = true; try { const res = await listTasks(query); rows.value = res.rows || [] } finally { loading.value = false } }
load()
</script>
